#!/bin/bash
J="/workspaces/dlh-cyber_security/cybersecurity_basics/0x03_cryptography_basics"; cd /tmp/john/run && ./john --format=raw-md5 --wordlist=/usr/share/wordlists/rockyou.txt $J/hash.txt && ./john --show $J/hash.txt | grep -v "password hash" | cut -d ':' -f2 | cut -d ' ' -f1 > $J/4-password.txt